head.script:
scwin.trigger1_onclick = function(e) {
    gridView1.initGrid();
    var jsonData2 = [{
        "col1": "b1"
    }, {
        "col1": "b2"
    }, {
        "col1": "b3"
    }];
    dataList1.setJSON(jsonData2);
};
scwin._getData = function() {
    var colDataArr = [];
    for (var i = 0; i < gridView1.getRowCount(); i++) {
        colDataArr.push(gridView1.getCellDisplayData(i, 'col2'));
    }
    return colDataArr;
}
scwin.__isChanged = function() {
    return JSON.stringify(oldArr) != JSON.stringify(scwin._getData());
}
scwin._checkErr = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("Cannot read property 'label' of undefined") == -1;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Design 탭에서 name2 의 inputType 을 확인한다.
    //1. In the Design tab, check the inputType of name2.
    //Verify 1. inputType="autoComplete"
    //Test step 2. 브라우저에서 name2 컬럼의 셀을 임의로 수정한다. (예 : '1' -> '2')
    //2. Modify the cell of the name2 column in the browser arbitrarily. (Example: '1' -> '2')
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_0_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#gridView1_cell_0_1 td:last').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2input_table_sb_main td:last').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. '1' -> '2' 로 변경된다.
    //2. Change from '1' to '2'.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_1').text() == '2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. init 후 gridView.setJSON 버튼을 클릭한다.
    //3. After init, click the gridView.setJSON button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 데이터가 변경된다.
    //3. The data is changed.
    WebSquare.wUnit.addCommand("assert", "scwin.__isChanged()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 로그 (Alt + 마우스 오른쪽) 를 실행시켜 에러로그가 있는지 확인한다.
    //4. Run the log (Alt + right mouse) to see if there is an error log.
    WebSquare.wUnit.addCommand("assert", "scwin._checkErr()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "value": "1",
        "label": "1"
    }, {
        "value": "2",
        "label": "2"
    }];
    dl_auto.setJSON(jsonData);
    window.jsonData2 = [{
        "col1": "a1",
        "col2": "1"
    }, {
        "col1": "a2",
        "col2": "1"
    }, {
        "col1": "a3",
        "col2": "1"
    }];
    dataList1.setJSON(jsonData2);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Feb-2018
    window.oldArr = scwin._getData();
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
